from pathlib import Path
import re
f=Path(__file__).parent/'contact.html'
s=f.read_text()
new="<section class=\"section\"><div class=\"wrap split\"><div><div class=\"eyebrow\">START A CONVERSATION</div><h2>Tell us your <em>big idea.</em></h2><p class=\"lead\">Submit your business, marketing, event or management inquiry. We will review it and contact you using the details provided.</p><div class=\"panel\"><h3>What happens next?</h3><p>1. We receive your inquiry.<br>2. We review your requirements.<br>3. Our team follows up when available.</p><p class=\"fine\">Submitting a request does not establish a client relationship.</p></div></div><form id=\"inquiry-form\" class=\"panel inquiry-form\"><h3>Request a Consultation</h3><label for=\"inquiry-name\">Full name *</label><input id=\"inquiry-name\" name=\"name\" autocomplete=\"name\" maxlength=\"100\" minlength=\"2\" required><label for=\"inquiry-email\">Email *</label><input id=\"inquiry-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"180\" required><label for=\"inquiry-phone\">Phone (optional)</label><input id=\"inquiry-phone\" name=\"phone\" autocomplete=\"tel\" type=\"tel\" maxlength=\"40\"><label for=\"inquiry-service\">What do you need? *</label><select id=\"inquiry-service\" name=\"service\" required><option value=\"\">Choose a service</option><option>Business Management</option><option>Marketing & Advertising</option><option>Business Consulting</option><option>Artist Management</option><option>Events & Nightlife</option><option>Project Management</option><option>Partnership</option><option>Other</option></select><label for=\"inquiry-message\">Tell us about your project *</label><textarea id=\"inquiry-message\" name=\"message\" rows=\"5\" minlength=\"15\" maxlength=\"3000\" required></textarea><div class=\"trap\" aria-hidden=\"true\"><label for=\"inquiry-website\">Website</label><input id=\"inquiry-website\" name=\"website\" tabindex=\"-1\" autocomplete=\"off\"></div><label class=\"consent\"><input name=\"consent\" type=\"checkbox\" required><span>I agree to have my information stored for the purpose of responding to my inquiry. *</span></label><button class=\"button gold\" type=\"submit\">Send Inquiry ↗</button><p id=\"inquiry-status\" role=\"status\" aria-live=\"polite\"></p><p class=\"fine\">We store submitted contact information and project details to respond to your request. We don't sell inquiry data. Please do not submit sensitive personal or financial information.</p></form></div></section>"
s=re.sub(r'(<main id="main">.*?</section>)(<section class="section">.*?</section>)(</main>)',lambda m:m.group(1)+new+m.group(3),s,flags=re.S)
f.write_text(s)

s=f.read_text()
s=s.replace("</head>","<script defer src=\"inquiry.js\"></script></head>")
f.write_text(s)
